// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 seed, uint256 amount) public {
        seed = bound(seed, 1, 1e30);
        amount = bound(amount, 0, 1e30);

        Sink sink = new Sink();
        vm.deal(address(c), seed);
        vm.deal(address(this), amount);

        bool ok;
        try c.Command{value: amount}(address(sink), "") {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a successful Command (owner-called, accepting callee, empty data)
        // forwards exactly msg.value, so c's pre-existing seed stays intact.
        assertTrue(!ok || address(c).balance == seed);
    }
}

contract Sink {
    receive() external payable {}
}
